package com.devsphere.ui;

import com.devsphere.model.*;import com.devsphere.service.*;import com.devsphere.dao.*;
import javax.swing.*;import java.awt.*;import java.sql.SQLException;

public class ContributionPanel extends JPanel{
 private final ContributionService service;private final Session session;private final JLabel summary=new JLabel();private final JTextArea breakdown=new JTextArea();private final JTextArea leaderboard=new JTextArea();private final JTextArea analytics=new JTextArea();private final DefaultListModel<String> recent=new DefaultListModel<>();private final ContributionHeatmapPanel heatmapPanel;
 public ContributionPanel(ContributionService service,Session session){this.service=service;this.session=session;this.heatmapPanel=new ContributionHeatmapPanel(service,session.userId());setLayout(new BorderLayout(0,12));setBackground(UiStyle.BACKGROUND);setBorder(BorderFactory.createEmptyBorder(24,36,30,36));add(header(),BorderLayout.NORTH);JPanel center=new JPanel(new GridLayout(1,2,14,0));center.setOpaque(false);center.add(summaryCard());JTabbedPane tabs=new JTabbedPane();tabs.addTab("Heatmap",heatmapCard());tabs.addTab("Recent activity",textCard("Activity timeline",recent));tabs.addTab("Leaderboard",areaCard("Developers",leaderboard));tabs.addTab("Project analytics",areaCard("Platform activity statistics",analytics));center.add(tabs);add(center,BorderLayout.CENTER);refresh();}
 private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JLabel title=UiStyle.heading("Contribution intelligence");p.add(title,BorderLayout.WEST);JButton refresh=new JButton("Refresh");UiStyle.button(refresh);refresh.addActionListener(e->refresh());p.add(refresh,BorderLayout.EAST);return p;}
 private JPanel summaryCard(){JPanel p=new JPanel(new BorderLayout(0,8));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createEmptyBorder(16,18,16,18));summary.setFont(new Font("SansSerif",Font.BOLD,22));breakdown.setEditable(false);breakdown.setOpaque(false);p.add(summary,BorderLayout.NORTH);p.add(new JScrollPane(breakdown),BorderLayout.CENTER);return p;}
 private JPanel textCard(String title,ListModel<String> model){JPanel p=new JPanel(new BorderLayout());p.setBackground(Color.WHITE);p.add(new JLabel(title),BorderLayout.NORTH);p.add(new JScrollPane(new JList<>(model)),BorderLayout.CENTER);return p;}
 private JPanel areaCard(String title,JTextArea area){JPanel p=new JPanel(new BorderLayout());p.setBackground(Color.WHITE);area.setEditable(false);p.add(new JLabel(title),BorderLayout.NORTH);p.add(new JScrollPane(area),BorderLayout.CENTER);return p;}
 private JPanel heatmapCard(){JPanel p=new JPanel(new BorderLayout());p.setBackground(Color.WHITE);p.add(heatmapPanel,BorderLayout.CENTER);return p;}
 public void refresh(){try{ContributionSummary s=service.summary(session.userId());summary.setText("Score: "+s.totalScore()+"   Activities: "+s.totalActivities());StringBuilder b=new StringBuilder("Recorded activity points (not verified productivity):\n");s.breakdown().forEach((k,v)->b.append(k).append(": ").append(v).append(" points\n"));breakdown.setText(b.toString());recent.clear();for(ContributionActivity a:service.recent(session.userId()))recent.addElement(a.createdAt()+" - "+a.activityType()+" ("+a.points()+" points)");StringBuilder ranks=new StringBuilder();for(LeaderboardRow row:service.leaderboard(null))ranks.append(row.rank()).append(". ").append(row.fullName()).append(" (@").append(row.username()).append(") - ").append(row.score()).append(" points / ").append(row.activityCount()).append(" activities\n");leaderboard.setText(ranks.toString());StringBuilder projectStats=new StringBuilder();for(Project project:new ProjectService(new ProjectDao(),new UserDao()).getProjectsForUser(session)){ProjectAnalytics a=service.analytics(project.id());projectStats.append(project.name()).append(": ").append(a.totalActivities()).append(" activities, ").append(a.contributingMembers()).append(" contributors, ").append(a.issuesCreated()).append(" issues created, ").append(a.issuesResolved()).append(" resolved; most active: ").append(a.mostActiveMember()).append("\n");}analytics.setText(projectStats.toString());heatmapPanel.refresh();}catch(SQLException e){summary.setText("Contribution data unavailable: "+e.getSQLState()+" / "+e.getErrorCode());}}
}
